target.css:
:root {
  --ink: #20313b;
  --muted: #65727a;
  --paper: #fffdf7;
  --line: #d8dfd9;
  --teal: #176b6d;
  --teal-pale: #dcefee;
  --coral: #e96b51;
}

.checkpoint-card {
  box-sizing: border-box;
  width: 480px;
  padding: 18px;
  border: 1px solid var(--line);
  border-top: 5px solid var(--teal);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line);
}

.title-block p,
.title-block h1,
.location-row p,
.schedule,
.schedule div {
  margin: 0;
}

.eyebrow {
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.2px;
  line-height: 1.2;
}

.title-block h1 {
  margin-top: 4px;
  font-size: 23px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  border-radius: 999px;
  background: var(--teal-pale);
  color: var(--teal);
  font-size: 12px;
  font-weight: 700;
}

.location-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 12px 0;
}

.location-icon {
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  border-radius: 8px;
  background: var(--coral);
  color: var(--paper);
  font-size: 15px;
}

.location-row p {
  display: grid;
  gap: 2px;
  font-size: 13px;
  line-height: 1.2;
}

.location-row strong {
  font-size: 14px;
}

.location-row p span {
  color: var(--muted);
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 142px;
  gap: 14px;
  padding: 12px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.schedule {
  display: grid;
  gap: 7px;
}

.schedule div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  font-size: 13px;
}

.schedule dt {
  color: var(--muted);
}

.schedule dd {
  margin: 0;
  color: var(--ink);
  font-weight: 700;
}

.stamp {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 8px;
  border: 1px dashed var(--coral);
  border-radius: 10px;
  background: var(--teal-pale);
}

.stamp-number {
  display: grid;
  width: 35px;
  height: 35px;
  place-items: center;
  border-radius: 50%;
  background: var(--coral);
  color: var(--paper);
  font-size: 16px;
  font-weight: 700;
}

.stamp figcaption {
  color: var(--teal);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 13px;
}

.progress {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
}

button {
  padding: 8px 12px;
  border: 0;
  border-radius: 8px;
  background: var(--teal);
  color: var(--paper);
  font-size: 13px;
  font-weight: 700;
}

